window.AUTH=window.AUTH||{};window.AUTH["22-429"]={"d":"22-429","id":"2023/22-429","n":"Acheson Hotels, LLC v. Laufer","briefs":[{"k":"petitioner","label":"Brief of petitioner Acheson Hotels, LLC","date":"2023-06-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-429/268427/20230605160031302_22-429%20ts.pdf","side":"pet","n":55},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2023-06-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-429/268948/20230612182635037_22-429npacUnitedStates.pdf","side":"us","n":74},{"k":"respondent","label":"Brief of respondent Deborah Laufer","date":"2023-08-02","url":"https://www.supremecourt.gov/DocketPDF/22/22-429/274500/20230802150335267_No%2022-429%20Acheson%20Hotels%20v.%20Laufer%20Respondents%20Brief%20Filed.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner Acheson Hotels, LLC","date":"2023-09-01","url":"https://www.supremecourt.gov/DocketPDF/22/22-429/278676/20230901100818356_22-429%20rb.pdf","side":"pet","n":21}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r01_q86b.pdf","tr":true,"items":[{"t":"case","label":"ACLU of Georgia v. Rabun County Chamber of Commerce, Inc.","cite":"698 F.2d 1098","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/698/1098/","by":{"0":"25"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"op":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"3, 39, 40, 41","1":"11, 23","2":"11, 34, 37","3":"1, 4, 5, 7, 8, 14"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"0":"15","1":"31","2":"49"}},{"t":"case","label":"American Humanist Ass’n v. MarylandNational Capital Park & Planning Commission","cite":"874 F.3d 195","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/195/","sum":"Finding standing when plaintiffs “regularly encountered the Cross as residents while driving in the area”.","sumSrc":"brief:0","by":{"0":"25"}},{"t":"case","label":"Brintley v. Aeroquip Credit Union","cite":"936 F.3d 489","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/936/489/","by":{"0":"24","3":"3, 6, 7"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"ar":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15"}},{"t":"case","label":"Carney v. Adams","cite":"141 S. Ct. 493","y":2020,"id":"2020/19-309","sc":1,"sum":"Because plaintiff Adams has not shown that he was “able and ready” to apply for a judicial vacancy in the imminent future, Gratz v. Bollinger, 539 U. S. 244, 262, he has failed to demonstrate Article III standing to challenge the Delaware Constitution’s political balance requirement for appointments to the State’s major courts.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24","3":"2"}},{"t":"case","label":"Casillas v. Madison Avenue Associates, Inc.","cite":"926 F.3d 329","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/329/","ar":1,"by":{"0":"33, 37, 39"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Clapper v. Amnesty International USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"43","1":"29","3":"15"}},{"t":"case","label":"Diamond v. Charles","cite":"476 U.S. 54","y":1986,"id":"1985/84-1379","sc":1,"sum":"Because appellant lacks any judicially cognizable interest in the Illinois Abortion Law, his appeal is dismissed for want of jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"FEC v. Akins","cite":"524 U.S. 11","y":1998,"id":"1997/96-1590","sc":1,"sum":"The Court held that voters seeking information, to which they believe FECA entitles them, have standing to challenge the FEC's decision not to bring an enforcement action. Because FECA seeks to address the voters' injury, the failure to obtain relevant information, Justice Breyer concluded that the voters had prudential standing.","sumSrc":"Oyez","by":{"0":"33, 34, 35","1":"7, 27, 28","2":"10, 34"}},{"t":"case","label":"Gill v. Whitford","cite":"138 S. Ct. 1916","y":2018,"id":"2017/16-1161","sc":1,"sum":"A case in which the Court was asked to decide whether partisan gerrymandering claims are justiciable, but the Court held that the plaintiffs lacked judicial standing.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"op":4,"ar":18,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 11, 12, 26, 27, 28, 29, 42","1":"6, 8, 9, 11-13, 17, 21, 22, 25","2":"3, 9, 14, 17, 21, 22, 23, 24, 27, 33, 40","3":"11, 12, 13"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"op":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Heckler v. Mathews","cite":"465 U.S. 728","y":1984,"id":"1983/82-1050","sc":1,"sum":"The unanimous Court upheld the law. Justice Brennan granted that the 1977 amendments temporarily revived gender-based eligibility requirements, but maintained that they served a legitimate government interest, namely, they protected individuals who had planned for their retirements relying on the law as it stood before the Court's Califano decision.","sumSrc":"Oyez","by":{"0":"38, 39","1":"13","2":"11, 17, 34, 35, 36, 37","3":"4"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"sum":"The Court found that the proponents of California's same-sex marriage ban (Proposition 8) do not have standing to appeal the decision that made Proposition 8 unconstitutional.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Laufer v. Arpan LLC","cite":"29 F.4th 1268","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/29/1268/","op":1,"by":{"0":"44","2":"11, 12","3":"23"}},{"t":"case","label":"Lewis v. Continental Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"sum":"Before 1987, the Bank Holding Company Act of 1956 (BHCA) allowed States to prohibit an out-of-state bank holding company from owning an in-state \"bank,\" which was defined to include an institution that both accepted demand deposits and engaged in the commercial lending business. In 1981, appellee, an Illinois bank holding company, applied to Florida to establish and operate an \"industrial savings bank\" (ISB) in that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 23, 24"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":4,"ar":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"21, 48","1":"11, 15, 26, 32","2":"41"}},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 35, 37","1":"7, 27, 28","2":"10"}},{"t":"case","label":"Schlesinger v. Reservists Committee to Stop the War","cite":"418 U.S. 208","y":1974,"id":"1973/72-1188","sc":1,"sum":"Respondents-an association of present and former members of the Armed Forces Reserve opposing United States involvement in Vietnam, and five association members who were United States citizens and taxpayers-brought a class action on behalf, inter alia, of all United States citizens and taxpayers against petitioners, the Secretary of Defense and the three Service Secretaries, challenging the Reserve membership of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"op":4,"ar":2,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"0":"19, 22","1":"9, 11, 13, 22, 24-26","2":"10, 34, 39, 40, 41"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"ar":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"16","2":"16, 31"}},{"t":"case","label":"Summers v. Earth Island Institute","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"0":"18, 19, 20"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Thole v. United States Bank N.A.","cite":"140 S. Ct. 1615","y":2020,"id":"2019/17-1712","sc":1,"sum":"The Court held that an ERISA plan participant lacks judicial standing to seek injunctive relief or restoration of plan losses caused by fiduciary breach if he cannot demonstrate individual financial loss or the imminent risk thereof.","sumSrc":"Oyez","by":{"0":"28","1":"21"}},{"t":"case","label":"vii TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"op":1,"ar":4,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2, 9, 11, 12, 13, 14, 15, 17, 18, 28, 29, 33, 39, 44, 45, 48, 52","1":"7, 10, 11, 21, 25-28","2":"3, 17, 21, 36, 41","3":"2, 9, 14, 19"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"sum":"The Court held that Richardson did not have standing to sue. Using the two-pronged standing test of Flast v. Cohen (1968), Chief Justice Burger found that there was no \"logical nexus between the status asserted [by Richardson as a taxpayer] and the claim sought to be adjudicated.\" It was clear to Burger that Richardson was not \"a proper and appropriate party to invoke federal judicial power\" on this issue.","sumSrc":"Oyez","by":{"0":"25","3":"3"}},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Virginia House of Delegates v. BethuneHill","cite":"139 S. Ct. 1945","y":2019,"id":"2018/18-281","sc":1,"sum":"The House of Delegates lacks standing to appeal the invalidation of Virginia’s redistricting plan.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"51"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 2000a-3","url":"https://www.law.cornell.edu/uscode/text/42/2000a-3","subs":["(a)"],"stext":{"head":"§2000a–3. Civil actions for injunctive relief","paras":[[0,"(a) Persons aggrieved; intervention by Attorney General; legal representation; commencement of action without payment of fees, costs, or security"],[0,"Whenever any person has engaged or there are reasonable grounds to believe that any person is about to engage in any act or practice prohibited by section 2000a–2 of this title, a civil action for preventive relief, including an application for a permanent or temporary injunction, restraining order, or other order, may be instituted by the person aggrieved and, upon timely application, the court may, in its discretion, permit the Attorney General to intervene in such civil action if he certifies that the case is of general public importance. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the civil action without the payment of fees, costs, or security."],[0,"(b) Attorney's fees; liability of United States for costs"],[0,"In any action commenced pursuant to this subchapter, the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee as part of the costs, and the United States shall be liable for costs the same as a private person."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; stay of Federal proceedings"],[0,"In the case of an alleged act or practice prohibited by this subchapter which occurs in a State, or political subdivision of a State, which has a State or local law prohibiting such act or practice and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no civil action may be brought under subsection (a) before the expiration of thirty days after written notice of such alleged act or practice has been given to the appropriate State or local authority by registered mail or in person, provided that the court may stay proceedings in such civil action pending the termination of State or local enforcement proceedings."],[0,"(d) References to Community Relations Service to obtain voluntary compliance; duration of reference; extension of period"],[0,"In the case of an alleged act or practice prohibited by this subchapter which occurs in a State, or political subdivision of a State, which has no State or local law prohibiting such act or practice, a civil action may be brought under subsection (a): Provided, That the court may refer the matter to the Community Relations Service established by subchapter VIII of this chapter for as long as the court believes there is a reasonable possibility of obtaining voluntary compliance, but for not more than sixty days: Provided further, That upon expiration of such sixty-day period, the court may extend such period for an additional period, not to exceed a cumulative total of one hundred and twenty days, if it believes there then exists a reasonable possibility of securing voluntary compliance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000a-3?type=usc&year=mostrecent&link-type=html"},"head":"§2000a–3. Civil actions for injunctive relief","tname":"The Public Health and Welfare","by":{"0":"4-5","1":"3"}},{"t":"usc","label":"42 U.S.C. § 3602","url":"https://www.law.cornell.edu/uscode/text/42/3602","subs":["(f)(1982)","(f)(2023)","(i)(2023)"],"by":{"0":"26, 26, 26"}},{"t":"usc","label":"42 U.S.C. § 3604","url":"https://www.law.cornell.edu/uscode/text/42/3604","subs":["(d)","(a)","(b)","(d)(1976)"],"stext":{"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","paras":[[0,"As made applicable by section 3603 of this title and except as exempted by sections 3603(b) and 3607 of this title, it shall be unlawful—"],[0,"(a) To refuse to sell or rent after the making of a bona fide offer, or to refuse to negotiate for the sale or rental of, or otherwise make unavailable or deny, a dwelling to any person because of race, color, religion, sex, familial status, or national origin."],[0,"(b) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection therewith, because of race, color, religion, sex, familial status, or national origin."],[0,"(c) To make, print, or publish, or cause to be made, printed, or published any notice, statement, or advertisement, with respect to the sale or rental of a dwelling that indicates any preference, limitation, or discrimination based on race, color, religion, sex, handicap, familial status, or national origin, or an intention to make any such preference, limitation, or discrimination."],[0,"(d) To represent to any person because of race, color, religion, sex, handicap, familial status, or national origin that any dwelling is not available for inspection, sale, or rental when such dwelling is in fact so available."],[0,"(e) For profit, to induce or attempt to induce any person to sell or rent any dwelling by representations regarding the entry or prospective entry into the neighborhood of a person or persons of a particular race, color, religion, sex, handicap, familial status, or national origin."],[0,"(f)(1) To discriminate in the sale or rental, or to otherwise make unavailable or deny, a dwelling to any buyer or renter because of a handicap of—"],[1,"(A) that buyer or renter,1"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that buyer or renter."],[0,"(2) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection with such dwelling, because of a handicap of—"],[1,"(A) that person; or"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that person."],[0,"(3) For purposes of this subsection, discrimination includes—"],[1,"(A) a refusal to permit, at the expense of the handicapped person, reasonable modifications of existing premises occupied or to be occupied by such person if such modifications may be necessary to afford such person full enjoyment of the premises except that, in the case of a rental, the landlord may where it is reasonable to do so condition permission for a modification on the renter agreeing to restore the interior of the premises to the condition that existed before the modification, reasonable wear and tear excepted.2"],[1,"(B) a refusal to make reasonable accommodations in rules, policies, practices, or services, when such accommodations may be necessary to afford such person equal opportunity to use and enjoy a dwelling; or"],[1,"(C) in connection with the design and construction of covered multifamily dwellings for first occupancy after the date that is 30 months after September 13, 1988, a failure to design and construct those dwellings in such a manner that—"],[2,"(i) the public use and common use portions of such dwellings are readily accessible to and usable by handicapped persons;"],[2,"(ii) all the doors designed to allow passage into and within all premises within such dwellings are sufficiently wide to allow passage by handicapped persons in wheelchairs; and"],[2,"(iii) all premises within such dwellings contain the following features of adaptive design:"],[3,"(I) an accessible route into and through the dwelling;"],[3,"(II) light switches, electrical outlets, thermostats, and other environmental controls in accessible locations;"],[3,"(III) reinforcements in bathroom walls to allow later installation of grab bars; and"],[3,"(IV) usable kitchens and bathrooms such that an individual in a wheelchair can maneuver about the space."],[0,"(4) Compliance with the appropriate requirements of the American National Standard for buildings and facilities providing accessibility and usability for physically handicapped people (commonly cited as \"ANSI A117.1\") suffices to satisfy the requirements of paragraph (3)(C)(iii)."],[0,"(5)(A) If a State or unit of general local government has incorporated into its laws the requirements set forth in paragraph (3)(C), compliance with such laws shall be deemed to satisfy the requirements of that paragraph."],[0,"(B) A State or unit of general local government may review and approve newly constructed covered multifamily dwellings for the purpose of making determinations as to whether the design and construction requirements of paragraph (3)(C) are met."],[0,"(C) The Secretary shall encourage, but may not require, States and units of local government to include in their existing procedures for the review and approval of newly constructed covered multifamily dwellings, determinations as to whether the design and construction of such dwellings are consistent with paragraph (3)(C), and shall provide technical assistance to States and units of local government and other persons to implement the requirements of paragraph (3)(C)."],[0,"(D) Nothing in this subchapter shall be construed to require the Secretary to review or approve the plans, designs or construction of all covered multifamily dwellings, to determine whether the design and construction of such dwellings are consistent with the requirements of paragraph 3(C)."],[0,"(6)(A) Nothing in paragraph (5) shall be construed to affect the authority and responsibility of the Secretary or a State or local public agency certified pursuant to section 3610(f)(3) of this title to receive and process complaints or otherwise engage in enforcement activities under this subchapter."],[0,"(B) Determinations by a State or a unit of general local government under paragraphs (5)(A) and (B) shall not be conclusive in enforcement proceedings under this subchapter."],[0,"(7) As used in this subsection, the term \"covered multifamily dwellings\" means—"],[1,"(A) buildings consisting of 4 or more units if such buildings have one or more elevators; and"],[1,"(B) ground floor units in other buildings consisting of 4 or more units."],[0,"(8) Nothing in this subchapter shall be construed to invalidate or limit any law of a State or political subdivision of a State, or other jurisdiction in which this subchapter shall be effective, that requires dwellings to be designed and constructed in a manner that affords handicapped persons greater access than is required by this subchapter."],[0,"(9) Nothing in this subsection requires that a dwelling be made available to an individual whose tenancy would constitute a direct threat to the health or safety of other individuals or whose tenancy would result in substantial physical damage to the property of others."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3604?type=usc&year=mostrecent&link-type=html"},"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","tname":"The Public Health and Welfare","by":{"0":"26","1":"14, 14, 12, 6, 13, 19, 14","2":"22, 23","3":"11"}},{"t":"usc","label":"42 U.S.C. § 3612","url":"https://www.law.cornell.edu/uscode/text/42/3612","subs":["(a)(1982)"],"stext":{"head":"§3612. Enforcement by Secretary","paras":[[0,"(a) Election of judicial determination"],[0,"When a charge is filed under section 3610 of this title, a complainant, a respondent, or an aggrieved person on whose behalf the complaint was filed, may elect to have the claims asserted in that charge decided in a civil action under subsection (o) in lieu of a hearing under subsection (b). The election must be made not later than 20 days after the receipt by the electing person of service under section 3610(h) of this title or, in the case of the Secretary, not later than 20 days after such service. The person making such election shall give notice of doing so to the Secretary and to all other complainants and respondents to whom the charge relates."],[0,"(b) Administrative law judge hearing in absence of election"],[0,"If an election is not made under subsection (a) with respect to a charge filed under section 3610 of this title, the Secretary shall provide an opportunity for a hearing on the record with respect to a charge issued under section 3610 of this title. The Secretary shall delegate the conduct of a hearing under this section to an administrative law judge appointed under section 3105 of title 5. The administrative law judge shall conduct the hearing at a place in the vicinity in which the discriminatory housing practice is alleged to have occurred or to be about to occur."],[0,"(c) Rights of parties"],[0,"At a hearing under this section, each party may appear in person, be represented by counsel, present evidence, cross-examine witnesses, and obtain the issuance of subpoenas under section 3611 of this title. Any aggrieved person may intervene as a party in the proceeding. The Federal Rules of Evidence apply to the presentation of evidence in such hearing as they would in a civil action in a United States district court."],[0,"(d) Expedited discovery and hearing"],[0,"(1) Discovery in administrative proceedings under this section shall be conducted as expeditiously and inexpensively as possible, consistent with the need of all parties to obtain relevant evidence."],[0,"(2) A hearing under this section shall be conducted as expeditiously and inexpensively as possible, consistent with the needs and rights of the parties to obtain a fair hearing and a complete record."],[0,"(3) The Secretary shall, not later than 180 days after September 13, 1988, issue rules to implement this subsection."],[0,"(e) Resolution of charge"],[0,"Any resolution of a charge before a final order under this section shall require the consent of the aggrieved person on whose behalf the charge is issued."],[0,"(f) Effect of trial of civil action on administrative proceedings"],[0,"An administrative law judge may not continue administrative proceedings under this section regarding any alleged discriminatory housing practice after the beginning of the trial of a civil action commenced by the aggrieved party under an Act of Congress or a State law, seeking relief with respect to that discriminatory housing practice."],[0,"(g) Hearings, findings and conclusions, and order"],[0,"(1) The administrative law judge shall commence the hearing under this section no later than 120 days following the issuance of the charge, unless it is impracticable to do so. If the administrative law judge is unable to commence the hearing within 120 days after the issuance of the charge, the administrative law judge shall notify the Secretary, the aggrieved person on whose behalf the charge was filed, and the respondent, in writing of the reasons for not doing so."],[0,"(2) The administrative law judge shall make findings of fact and conclusions of law within 60 days after the end of the hearing under this section, unless it is impracticable to do so. If the administrative law judge is unable to make findings of fact and conclusions of law within such period, or any succeeding 60-day period thereafter, the administrative law judge shall notify the Secretary, the aggrieved person on whose behalf the charge was filed, and the respondent, in writing of the reasons for not doing so."],[0,"(3) If the administrative law judge finds that a respondent has engaged or is about to engage in a discriminatory housing practice, such administrative law judge shall promptly issue an order for such relief as may be appropriate, which may include actual damages suffered by the aggrieved person and injunctive or other equitable relief. Such order may, to vindicate the public interest, assess a civil penalty against the respondent—"],[1,"(A) in an amount not exceeding $10,000 if the respondent has not been adjudged to have committed any prior discriminatory housing practice;"],[1,"(B) in an amount not exceeding $25,000 if the respondent has been adjudged to have committed one other discriminatory housing practice during the 5-year period ending on the date of the filing of this charge; and"],[1,"(C) in an amount not exceeding $50,000 if the respondent has been adjudged to have committed 2 or more discriminatory housing practices during the 7-year period ending on the date of the filing of this charge;"],[0,"except that if the acts constituting the discriminatory housing practice that is the object of the charge are committed by the same natural person who has been previously adjudged to have committed acts constituting a discriminatory housing practice, then the civil penalties set forth in subparagraphs (B) and (C) may be imposed without regard to the period of time within which any subsequent discriminatory housing practice occurred."],[0,"(4) No such order shall affect any contract, sale, encumbrance, or lease consummated before the issuance of such order and involving a bona fide purchaser, encumbrancer, or tenant without actual notice of the charge filed under this subchapter."],[0,"(5) In the case of an order with respect to a discriminatory housing practice that occurred in the course of a business subject to a licensing or regulation by a governmental agency, the Secretary shall, not later than 30 days after the date of the issuance of such order (or, if such order is judicially reviewed, 30 days after such order is in substance affirmed upon such review)—"],[1,"(A) send copies of the findings of fact, conclusions of law, and the order, to that governmental agency; and"],[1,"(B) recommend to that governmental agency appropriate disciplinary action (including, where appropriate, the suspension or revocation of the license of the respondent)."],[0,"(6) In the case of an order against a respondent against whom another order was issued within the preceding 5 years under this section, the Secretary shall send a copy of each such order to the Attorney General."],[0,"(7) If the administrative law judge finds that the respondent has not engaged or is not about to engage in a discriminatory housing practice, as the case may be, such administrative law judge shall enter an order dismissing the charge. The Secretary shall make public disclosure of each such dismissal."],[0,"(h) Review by Secretary; service of final order"],[0,"(1) The Secretary may review any finding, conclusion, or order issued under subsection (g). Such review shall be completed not later than 30 days after the finding, conclusion, or order is so issued; otherwise the finding, conclusion, or order becomes final."],[0,"(2) The Secretary shall cause the findings of fact and conclusions of law made with respect to any final order for relief under this section, together with a copy of such order, to be served on each aggrieved person and each respondent in the proceeding."],[0,"(i) Judicial review"],[0,"(1) Any party aggrieved by a final order for relief under this section granting or denying in whole or in part the relief sought may obtain a review of such order under chapter 158 of title 28."],[0,"(2) Notwithstanding such chapter, venue of the proceeding shall be in the judicial circuit in which the discriminatory housing practice is alleged to have occurred, and filing of the petition for review shall be not later than 30 days after the order is entered."],[0,"(j) Court enforcement of administrative order upon petition by Secretary"],[0,"(1) The Secretary may petition any United States court of appeals for the circuit in which the discriminatory housing practice is alleged to have occurred or in which any respondent resides or transacts business for the enforcement of the order of the administrative law judge and for appropriate temporary relief or restraining order, by filing in such court a written petition praying that such order be enforced and for appropriate temporary relief or restraining order."],[0,"(2) The Secretary shall file in court with the petition the record in the proceeding. A copy of such petition shall be forthwith transmitted by the clerk of the court to the parties to the proceeding before the administrative law judge."],[0,"(k) Relief which may be granted"],[0,"(1) Upon the filing of a petition under subsection (i) or (j), the court may—"],[1,"(A) grant to the petitioner, or any other party, such temporary relief, restraining order, or other order as the court deems just and proper;"],[1,"(B) affirm, modify, or set aside, in whole or in part, the order, or remand the order for further proceedings; and"],[1,"(C) enforce such order to the extent that such order is affirmed or modified."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3612?type=usc&year=mostrecent&link-type=html"},"head":"§3612. Enforcement by Secretary","tname":"The Public Health and Welfare","by":{"0":"26","3":"11"}},{"t":"usc","label":"42 U.S.C. § 3613","url":"https://www.law.cornell.edu/uscode/text/42/3613","subs":["(a)"],"by":{"0":"26"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","subs":["(a)(5)"],"stext":{"head":"§12101. Findings and purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) physical or mental disabilities in no way diminish a person's right to fully participate in all aspects of society, yet many people with physical or mental disabilities have been precluded from doing so because of discrimination; others who have a record of a disability or are regarded as having a disability also have been subjected to discrimination;"],[1,"(2) historically, society has tended to isolate and segregate individuals with disabilities, and, despite some improvements, such forms of discrimination against individuals with disabilities continue to be a serious and pervasive social problem;"],[1,"(3) discrimination against individuals with disabilities persists in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and access to public services;"],[1,"(4) unlike individuals who have experienced discrimination on the basis of race, color, sex, national origin, religion, or age, individuals who have experienced discrimination on the basis of disability have often had no legal recourse to redress such discrimination;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination, including outright intentional exclusion, the discriminatory effects of architectural, transportation, and communication barriers, overprotective rules and policies, failure to make modifications to existing facilities and practices, exclusionary qualification standards and criteria, segregation, and relegation to lesser services, programs, activities, benefits, jobs, or other opportunities;"],[1,"(6) census data, national polls, and other studies have documented that people with disabilities, as a group, occupy an inferior status in our society, and are severely disadvantaged socially, vocationally, economically, and educationally;"],[1,"(7) the Nation's proper goals regarding individuals with disabilities are to assure equality of opportunity, full participation, independent living, and economic self-sufficiency for such individuals; and"],[1,"(8) the continuing existence of unfair and unnecessary discrimination and prejudice denies people with disabilities the opportunity to compete on an equal basis and to pursue those opportunities for which our free society is justifiably famous, and costs the United States billions of dollars in unnecessary expenses resulting from dependency and nonproductivity."],[0,"(b) Purpose"],[0,"It is the purpose of this chapter—"],[1,"(1) to provide a clear and comprehensive national mandate for the elimination of discrimination against individuals with disabilities;"],[1,"(2) to provide clear, strong, consistent, enforceable standards addressing discrimination against individuals with disabilities;"],[1,"(3) to ensure that the Federal Government plays a central role in enforcing the standards established in this chapter on behalf of individuals with disabilities; and"],[1,"(4) to invoke the sweep of congressional authority, including the power to enforce the fourteenth amendment and to regulate commerce, in order to address the major areas of discrimination faced day-to-day by people with disabilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12101. Findings and purpose","tname":"The Public Health and Welfare","by":{"0":"40","1":"1, 2, 3","2":"4, 5, 36, 45"}},{"t":"usc","label":"42 U.S.C. § 12181","url":"https://www.law.cornell.edu/uscode/text/42/12181","subs":["(7)","(7)(A)"],"stext":{"head":"§12181. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commerce"],[1,"The term \"commerce\" means travel, trade, traffic, commerce, transportation, or communication—"],[2,"(A) among the several States;"],[2,"(B) between any foreign country or any territory or possession and any State; or"],[2,"(C) between points in the same State but through another State or foreign country."],[0,"(2) Commercial facilities"],[1,"The term \"commercial facilities\" means facilities—"],[2,"(A) that are intended for nonresidential use; and"],[2,"(B) whose operations will affect commerce."],[1,"Such term shall not include railroad locomotives, railroad freight cars, railroad cabooses, railroad cars described in section 12162 of this title or covered under this subchapter, railroad rights-of-way, or facilities that are covered or expressly exempted from coverage under the Fair Housing Act of 1968 1 (42 U.S.C. 3601 et seq.)."],[0,"(3) Demand responsive system"],[1,"The term \"demand responsive system\" means any system of providing transportation of individuals by a vehicle, other than a system which is a fixed route system."],[0,"(4) Fixed route system"],[1,"The term \"fixed route system\" means a system of providing transportation of individuals (other than by aircraft) on which a vehicle is operated along a prescribed route according to a fixed schedule."],[0,"(5) Over-the-road bus"],[1,"The term \"over-the-road bus\" means a bus characterized by an elevated passenger deck located over a baggage compartment."],[0,"(6) Private entity"],[1,"The term \"private entity\" means any entity other than a public entity (as defined in section 12131(1) of this title)."],[0,"(7) Public accommodation"],[1,"The following private entities are considered public accommodations for purposes of this subchapter, if the operations of such entities affect commerce—"],[2,"(A) an inn, hotel, motel, or other place of lodging, except for an establishment located within a building that contains not more than five rooms for rent or hire and that is actually occupied by the proprietor of such establishment as the residence of such proprietor;"],[2,"(B) a restaurant, bar, or other establishment serving food or drink;"],[2,"(C) a motion picture house, theater, concert hall, stadium, or other place of exhibition or entertainment;"],[2,"(D) an auditorium, convention center, lecture hall, or other place of public gathering;"],[2,"(E) a bakery, grocery store, clothing store, hardware store, shopping center, or other sales or rental establishment;"],[2,"(F) a laundromat, dry-cleaner, bank, barber shop, beauty shop, travel service, shoe repair service, funeral parlor, gas station, office of an accountant or lawyer, pharmacy, insurance office, professional office of a health care provider, hospital, or other service establishment;"],[2,"(G) a terminal, depot, or other station used for specified public transportation;"],[2,"(H) a museum, library, gallery, or other place of public display or collection;"],[2,"(I) a park, zoo, amusement park, or other place of recreation;"],[2,"(J) a nursery, elementary, secondary, undergraduate, or postgraduate private school, or other place of education;"],[2,"(K) a day care center, senior citizen center, homeless shelter, food bank, adoption agency, or other social service center establishment; and"],[2,"(L) a gymnasium, health spa, bowling alley, golf course, or other place of exercise or recreation."],[0,"(8) Rail and railroad"],[1,"The terms \"rail\" and \"railroad\" have the meaning given the term \"railroad\" in section 20102(1) 1 of title 49."],[0,"(9) Readily achievable"],[1,"The term \"readily achievable\" means easily accomplishable and able to be carried out without much difficulty or expense. In determining whether an action is readily achievable, factors to be considered include—"],[2,"(A) the nature and cost of the action needed under this chapter;"],[2,"(B) the overall financial resources of the facility or facilities involved in the action; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such action upon the operation of the facility;"],[2,"(C) the overall financial resources of the covered entity; the overall size of the business of a covered entity with respect to the number of its employees; the number, type, and location of its facilities; and"],[2,"(D) the type of operation or operations of the covered entity, including the composition, structure, and functions of the workforce of such entity; the geographic separateness, administrative or fiscal relationship of the facility or facilities in question to the covered entity."],[0,"(10) Specified public transportation"],[1,"The term \"specified public transportation\" means transportation by bus, rail, or any other conveyance (other than by aircraft) that provides the general public with general or special service (including charter service) on a regular and continuing basis."],[0,"(11) Vehicle"],[1,"The term \"vehicle\" does not include a rail passenger car, railroad locomotive, railroad freight car, railroad caboose, or a railroad car described in section 12162 of this title or covered under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12181?type=usc&year=mostrecent&link-type=html"},"head":"§12181. Definitions","tname":"The Public Health and Welfare","by":{"0":"1, 20","1":"1-4, 9, 14-17, 19-23, 26, 28, 2","2":"5"}},{"t":"usc","label":"42 U.S.C. § 12182","url":"https://www.law.cornell.edu/uscode/text/42/12182","subs":["(a)","(b)(2)(A)(ii)","(b)(2)(A)(iv)","(b)(1)(A)(ii)"],"stext":{"head":"§12182. Prohibition of discrimination by public accommodations","paras":[[0,"(a) General rule"],[0,"No individual shall be discriminated against on the basis of disability in the full and equal enjoyment of the goods, services, facilities, privileges, advantages, or accommodations of any place of public accommodation by any person who owns, leases (or leases to), or operates a place of public accommodation."],[0,"(b) Construction"],[0,"(1) General prohibition"],[0,"(A) Activities"],[0,"(i) Denial of participation"],[3,"It shall be discriminatory to subject an individual or class of individuals on the basis of a disability or disabilities of such individual or class, directly, or through contractual, licensing, or other arrangements, to a denial of the opportunity of the individual or class to participate in or benefit from the goods, services, facilities, privileges, advantages, or accommodations of an entity."],[0,"(ii) Participation in unequal benefit"],[3,"It shall be discriminatory to afford an individual or class of individuals, on the basis of a disability or disabilities of such individual or class, directly, or through contractual, licensing, or other arrangements with the opportunity to participate in or benefit from a good, service, facility, privilege, advantage, or accommodation that is not equal to that afforded to other individuals."],[0,"(iii) Separate benefit"],[3,"It shall be discriminatory to provide an individual or class of individuals, on the basis of a disability or disabilities of such individual or class, directly, or through contractual, licensing, or other arrangements with a good, service, facility, privilege, advantage, or accommodation that is different or separate from that provided to other individuals, unless such action is necessary to provide the individual or class of individuals with a good, service, facility, privilege, advantage, or accommodation, or other opportunity that is as effective as that provided to others."],[0,"(iv) Individual or class of individuals"],[3,"For purposes of clauses (i) through (iii) of this subparagraph, the term \"individual or class of individuals\" refers to the clients or customers of the covered public accommodation that enters into the contractual, licensing or other arrangement."],[0,"(B) Integrated settings"],[2,"Goods, services, facilities, privileges, advantages, and accommodations shall be afforded to an individual with a disability in the most integrated setting appropriate to the needs of the individual."],[0,"(C) Opportunity to participate"],[2,"Notwithstanding the existence of separate or different programs or activities provided in accordance with this section, an individual with a disability shall not be denied the opportunity to participate in such programs or activities that are not separate or different."],[0,"(D) Administrative methods"],[2,"An individual or entity shall not, directly or through contractual or other arrangements, utilize standards or criteria or methods of administration—"],[3,"(i) that have the effect of discriminating on the basis of disability; or"],[3,"(ii) that perpetuate the discrimination of others who are subject to common administrative control."],[0,"(E) Association"],[2,"It shall be discriminatory to exclude or otherwise deny equal goods, services, facilities, privileges, advantages, accommodations, or other opportunities to an individual or entity because of the known disability of an individual with whom the individual or entity is known to have a relationship or association."],[0,"(2) Specific prohibitions"],[0,"(A) Discrimination"],[2,"For purposes of subsection (a), discrimination includes—"],[3,"(i) the imposition or application of eligibility criteria that screen out or tend to screen out an individual with a disability or any class of individuals with disabilities from fully and equally enjoying any goods, services, facilities, privileges, advantages, or accommodations, unless such criteria can be shown to be necessary for the provision of the goods, services, facilities, privileges, advantages, or accommodations being offered;"],[3,"(ii) a failure to make reasonable modifications in policies, practices, or procedures, when such modifications are necessary to afford such goods, services, facilities, privileges, advantages, or accommodations to individuals with disabilities, unless the entity can demonstrate that making such modifications would fundamentally alter the nature of such goods, services, facilities, privileges, advantages, or accommodations;"],[3,"(iii) a failure to take such steps as may be necessary to ensure that no individual with a disability is excluded, denied services, segregated or otherwise treated differently than other individuals because of the absence of auxiliary aids and services, unless the entity can demonstrate that taking such steps would fundamentally alter the nature of the good, service, facility, privilege, advantage, or accommodation being offered or would result in an undue burden;"],[3,"(iv) a failure to remove architectural barriers, and communication barriers that are structural in nature, in existing facilities, and transportation barriers in existing vehicles and rail passenger cars used by an establishment for transporting individuals (not including barriers that can only be removed through the retrofitting of vehicles or rail passenger cars by the installation of a hydraulic or other lift), where such removal is readily achievable; and"],[3,"(v) where an entity can demonstrate that the removal of a barrier under clause (iv) is not readily achievable, a failure to make such goods, services, facilities, privileges, advantages, or accommodations available through alternative methods if such methods are readily achievable."],[0,"(B) Fixed route system"],[0,"(i) Accessibility"],[3,"It shall be considered discrimination for a private entity which operates a fixed route system and which is not subject to section 12184 of this title to purchase or lease a vehicle with a seating capacity in excess of 16 passengers (including the driver) for use on such system, for which a solicitation is made after the 30th day following the effective date of this subparagraph, that is not readily accessible to and usable by individuals with disabilities, including individuals who use wheelchairs."],[0,"(ii) Equivalent service"],[3,"If a private entity which operates a fixed route system and which is not subject to section 12184 of this title purchases or leases a vehicle with a seating capacity of 16 passengers or less (including the driver) for use on such system after the effective date of this subparagraph that is not readily accessible to or usable by individuals with disabilities, it shall be considered discrimination for such entity to fail to operate such system so that, when viewed in its entirety, such system ensures a level of service to individuals with disabilities, including individuals who use wheelchairs, equivalent to the level of service provided to individuals without disabilities."],[0,"(C) Demand responsive system"],[2,"For purposes of subsection (a), discrimination includes—"],[3,"(i) a failure of a private entity which operates a demand responsive system and which is not subject to section 12184 of this title to operate such system so that, when viewed in its entirety, such system ensures a level of service to individuals with disabilities, including individuals who use wheelchairs, equivalent to the level of service provided to individuals without disabilities; and"],[3,"(ii) the purchase or lease by such entity for use on such system of a vehicle with a seating capacity in excess of 16 passengers (including the driver), for which solicitations are made after the 30th day following the effective date of this subparagraph, that is not readily accessible to and usable by individuals with disabilities (including individuals who use wheelchairs) unless such entity can demonstrate that such system, when viewed in its entirety, provides a level of service to individuals with disabilities equivalent to that provided to individuals without disabilities."],[0,"(D) Over-the-road buses"],[0,"(i) Limitation on applicability"],[3,"Subparagraphs (B) and (C) do not apply to over-the-road buses."],[0,"(ii) Accessibility requirements"],[3,"For purposes of subsection (a), discrimination includes (I) the purchase or lease of an over-the-road bus which does not comply with the regulations issued under section 12186(a)(2) of this title by a private entity which provides transportation of individuals and which is not primarily engaged in the business of transporting people, and (II) any other failure of such entity to comply with such regulations."],[0,"(3) Specific construction"],[1,"Nothing in this subchapter shall require an entity to permit an individual to participate in or benefit from the goods, services, facilities, privileges, advantages and accommodations of such entity where such individual poses a direct threat to the health or safety of others. The term \"direct threat\" means a significant risk to the health or safety of others that cannot be eliminated by a modification of policies, practices, or procedures or by the provision of auxiliary aids or services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12182?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§12182. Prohibition of discrimination by public accommodations","tname":"The Public Health and Welfare","by":{"0":"1, 4, 19, 31, 4, 6","1":"3, 22, 3, 22, 3, 22","2":"i, 1, 5, 6, 15, 16, 21, 25, 27, 33","3":"5, 6"}},{"t":"usc","label":"42 U.S.C. § 12186","url":"https://www.law.cornell.edu/uscode/text/42/12186","subs":["(b)"],"stext":{"head":"§12186. Regulations","paras":[[0,"(a) Transportation provisions"],[0,"(1) General rule"],[1,"Not later than 1 year after July 26, 1990, the Secretary of Transportation shall issue regulations in an accessible format to carry out sections 1 12182(b)(2)(B) and (C) of this title and to carry out section 12184 of this title (other than subsection (b)(4))."],[0,"(2) Special rules for providing access to over-the-road buses"],[0,"(A) Interim requirements"],[0,"(i) Issuance"],[3,"Not later than 1 year after July 26, 1990, the Secretary of Transportation shall issue regulations in an accessible format to carry out sections 12184(b)(4) and 12182(b)(2)(D)(ii) of this title that require each private entity which uses an over-the-road bus to provide transportation of individuals to provide accessibility to such bus; except that such regulations shall not require any structural changes in over-the-road buses in order to provide access to individuals who use wheelchairs during the effective period of such regulations and shall not require the purchase of boarding assistance devices to provide access to such individuals."],[0,"(ii) Effective period"],[3,"The regulations issued pursuant to this subparagraph shall be effective until the effective date of the regulations issued under subparagraph (B)."],[0,"(B) Final requirement"],[0,"(i) Review of study and interim requirements"],[3,"The Secretary shall review the study submitted under section 12185 of this title and the regulations issued pursuant to subparagraph (A)."],[0,"(ii) Issuance"],[3,"Not later than 1 year after the date of the submission of the study under section 12185 of this title, the Secretary shall issue in an accessible format new regulations to carry out sections 12184(b)(4) and 12182(b)(2)(D)(ii) of this title that require, taking into account the purposes of the study under section 12185 of this title and any recommendations resulting from such study, each private entity which uses an over-the-road bus to provide transportation to individuals to provide accessibility to such bus to individuals with disabilities, including individuals who use wheelchairs."],[0,"(iii) Effective period"],[3,"Subject to section 12185(d) of this title, the regulations issued pursuant to this subparagraph shall take effect—"],[4,"(I) with respect to small providers of transportation (as defined by the Secretary), 3 years after the date of issuance of final regulations under clause (ii); and"],[4,"(II) with respect to other providers of transportation, 2 years after the date of issuance of such final regulations."],[0,"(C) Limitation on requiring installation of accessible restrooms"],[2,"The regulations issued pursuant to this paragraph shall not require the installation of accessible restrooms in over-the-road buses if such installation would result in a loss of seating capacity."],[0,"(3) Standards"],[1,"The regulations issued pursuant to this subsection shall include standards applicable to facilities and vehicles covered by sections 12182(b)(2) and 12184 of this title."],[0,"(b) Other provisions"],[0,"Not later than 1 year after July 26, 1990, the Attorney General shall issue regulations in an accessible format to carry out the provisions of this subchapter not referred to in subsection (a) that include standards applicable to facilities and vehicles covered under section 12182 of this title."],[0,"(c) Consistency with ATBCB guidelines"],[0,"Standards included in regulations issued under subsections (a) and (b) shall be consistent with the minimum guidelines and requirements issued by the Architectural and Transportation Barriers Compliance Board in accordance with section 12204 of this title."],[0,"(d) Interim accessibility standards"],[0,"(1) Facilities"],[1,"If final regulations have not been issued pursuant to this section, for new construction or alterations for which a valid and appropriate State or local building permit is obtained prior to the issuance of final regulations under this section, and for which the construction or alteration authorized by such permit begins within one year of the receipt of such permit and is completed under the terms of such permit, compliance with the Uniform Federal Accessibility Standards in effect at the time the building permit is issued shall suffice to satisfy the requirement that facilities be readily accessible to and usable by persons with disabilities as required under section 12183 of this title, except that, if such final regulations have not been issued one year after the Architectural and Transportation Barriers Compliance Board has issued the supplemental minimum guidelines required under section 12204(a) of this title, compliance with such supplemental minimum guidelines shall be necessary to satisfy the requirement that facilities be readily accessible to and usable by persons with disabilities prior to issuance of the final regulations."],[0,"(2) Vehicles and rail passenger cars"],[1,"If final regulations have not been issued pursuant to this section, a private entity shall be considered to have complied with the requirements of this subchapter, if any, that a vehicle or rail passenger car be readily accessible to and usable by individuals with disabilities, if the design for such vehicle or car complies with the laws and regulations (including the Minimum Guidelines and Requirements for Accessible Design and such supplemental minimum guidelines as are issued under section 12204(a) of this title) governing accessibility of such vehicles or cars, to the extent that such laws and regulations are not inconsistent with this subchapter and are in effect at the time such design is substantially completed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12186?type=usc&year=mostrecent&link-type=html"},"head":"§12186. Regulations","tname":"The Public Health and Welfare","by":{"0":"4","1":"3, 22","2":"5"}},{"t":"usc","label":"42 U.S.C. § 12188","url":"https://www.law.cornell.edu/uscode/text/42/12188","subs":["(a)(1)","(b)(1)(B)"],"stext":{"head":"§12188. Enforcement","paras":[[0,"(a) In general"],[0,"(1) Availability of remedies and procedures"],[1,"The remedies and procedures set forth in section 2000a–3(a) of this title are the remedies and procedures this subchapter provides to any person who is being subjected to discrimination on the basis of disability in violation of this subchapter or who has reasonable grounds for believing that such person is about to be subjected to discrimination in violation of section 12183 of this title. Nothing in this section shall require a person with a disability to engage in a futile gesture if such person has actual notice that a person or organization covered by this subchapter does not intend to comply with its provisions."],[0,"(2) Injunctive relief"],[1,"In the case of violations of sections 12182(b)(2)(A)(iv) and section 1 12183(a) of this title, injunctive relief shall include an order to alter facilities to make such facilities readily accessible to and usable by individuals with disabilities to the extent required by this subchapter. Where appropriate, injunctive relief shall also include requiring the provision of an auxiliary aid or service, modification of a policy, or provision of alternative methods, to the extent required by this subchapter."],[0,"(b) Enforcement by Attorney General"],[0,"(1) Denial of rights"],[0,"(A) Duty to investigate"],[0,"(i) In general"],[3,"The Attorney General shall investigate alleged violations of this subchapter, and shall undertake periodic reviews of compliance of covered entities under this subchapter."],[0,"(ii) Attorney General certification"],[3,"On the application of a State or local government, the Attorney General may, in consultation with the Architectural and Transportation Barriers Compliance Board, and after prior notice and a public hearing at which persons, including individuals with disabilities, are provided an opportunity to testify against such certification, certify that a State law or local building code or similar ordinance that establishes accessibility requirements meets or exceeds the minimum requirements of this chapter for the accessibility and usability of covered facilities under this subchapter. At any enforcement proceeding under this section, such certification by the Attorney General shall be rebuttable evidence that such State law or local ordinance does meet or exceed the minimum requirements of this chapter."],[0,"(B) Potential violation"],[2,"If the Attorney General has reasonable cause to believe that—"],[3,"(i) any person or group of persons is engaged in a pattern or practice of discrimination under this subchapter; or"],[3,"(ii) any person or group of persons has been discriminated against under this subchapter and such discrimination raises an issue of general public importance,"],[2,"the Attorney General may commence a civil action in any appropriate United States district court."],[0,"(2) Authority of court"],[1,"In a civil action under paragraph (1)(B), the court—"],[2,"(A) may grant any equitable relief that such court considers to be appropriate, including, to the extent required by this subchapter—"],[3,"(i) granting temporary, preliminary, or permanent relief;"],[3,"(ii) providing an auxiliary aid or service, modification of policy, practice, or procedure, or alternative method; and"],[3,"(iii) making facilities readily accessible to and usable by individuals with disabilities;"],[2,"(B) may award such other relief as the court considers to be appropriate, including monetary damages to persons aggrieved when requested by the Attorney General; and"],[2,"(C) may, to vindicate the public interest, assess a civil penalty against the entity in an amount—"],[3,"(i) not exceeding $50,000 for a first violation; and"],[3,"(ii) not exceeding $100,000 for any subsequent violation."],[0,"(3) Single violation"],[1,"For purposes of paragraph (2)(C), in determining whether a first or subsequent violation has occurred, a determination in a single action, by judgment or settlement, that the covered entity has engaged in more than one discriminatory act shall be counted as a single violation."],[0,"(4) Punitive damages"],[1,"For purposes of subsection (b)(2)(B), the term \"monetary damages\" and \"such other relief\" does not include punitive damages."],[0,"(5) Judicial consideration"],[1,"In a civil action under paragraph (1)(B), the court, when considering what amount of civil penalty, if any, is appropriate, shall give consideration to any good faith effort or attempt to comply with this chapter by the entity. In evaluating good faith, the court shall consider, among other factors it deems relevant, whether the entity could have reasonably anticipated the need for an appropriate type of auxiliary aid needed to accommodate the unique needs of a particular individual with a disability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12188?type=usc&year=mostrecent&link-type=html"},"head":"§12188. Enforcement","tname":"The Public Health and Welfare","by":{"0":"4-5, 30","1":"3, 3","2":"3, 7, 23, 25, 29, 39"}},{"t":"usc","label":"42 U.S.C. § 12205","url":"https://www.law.cornell.edu/uscode/text/42/12205","stext":{"head":"§12205. Attorney's fees","paras":[[0,"In any action or administrative proceeding commenced pursuant to this chapter, the court or agency, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee, including litigation expenses, and costs, and the United States shall be liable for the foregoing the same as a private individual."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12205?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12205. Attorney's fees","tname":"The Public Health and Welfare","by":{"0":"5","1":"3"}},{"t":"law","label":"Pub. L. No. 100-430","url":"https://www.govinfo.gov/link/statute/102/1619","by":{"0":"26"}},{"t":"reg","label":"28 C.F.R. § 36.302","url":"https://www.ecfr.gov/current/title-28/section-36.302","subs":["(e)(1)(ii)"],"by":{"0":"2, 4, 20, 30","2":"1, 5, 6, 25, 49, 50","3":"4, 17"}},{"t":"reg","label":"28 C.F.R. § 36.501","url":"https://www.ecfr.gov/current/title-28/section-36.501","subs":["(a)"],"by":{"0":"31, 5"}},{"t":"reg","label":"28 C.F.R. § 36.505","url":"https://www.ecfr.gov/current/title-28/section-36.505","by":{"0":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 25","url":"https://www.law.cornell.edu/rules/frcp/rule_25","subs":["(c)"],"by":{"0":"5","3":"24"}},{"t":"reg","label":"Nondiscrimination on the Basis of Disability by Public Accommodations and in Commercial Facilities, 75 Fed. Reg. 56,237","url":"https://www.govinfo.gov/link/fr/75/56237","by":{"0":"4, 20, 32"}},{"t":"case","label":"Alvarez v. Smith","cite":"558 U.S. 87","y":2009,"id":"2009/08-351","sc":1,"op":1,"sum":"A case which the Court dismissed regarding property seizure under the Illinois Drug Asset Forfeiture Procedure Act (DAFPA).","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"1":"13","2":"35"}},{"t":"case","label":"Chicago & Nw. Ry. Co. v. Williams","cite":"55 Ill. 185","y":1870,"url":"https://www.courtlistener.com/c/Ill./55/185/","by":{"1":"27"}},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30"}},{"t":"case","label":"Colorado Cross-Disability Coal. v. Abercrombie & Fitch Co.","cite":"765 F.3d 1205","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/765/1205/","op":1,"by":{"1":"14-16","2":"24"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"op":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Evers v. Dwyer","cite":"358 U.S. 202","y":1958,"id":"1958/382","sc":1,"sum":"The record in this case establishes the existence of an actual controversy which should have been adjudicated by the District Court. Pp. 202-204. Reversed and case remanded for further proceedings. Robert L. Carterfor appellants. Walter Chandler, Allison B. Humphreys, Edward P. Russell and Charles M. Crump for appellees.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29","2":"40"}},{"t":"case","label":"FEC v. Cruz","cite":"142 S. Ct. 1638","y":2022,"id":"2021/21-12","sc":1,"ar":1,"sum":"Section 304 of the Bipartisan Campaign Reform Act of 2002—which limits the amount of post-election contributions that may be used to repay a candidate who lends money to his own campaign—unconstitutionally burdens core political speech.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21, 29","2":"33, 40","3":"15"}},{"t":"case","label":"Fleming v. Gutierrez","cite":"785 F.3d 442","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/442/","by":{"1":"32"}},{"t":"case","label":"Hillesheim v. Holiday Stationstores, Inc.","cite":"953 F.3d 1059","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/1059/","by":{"1":"30"}},{"t":"case","label":"Houston v. Marod Supermarkets, Inc.","cite":"733 F.3d 1323","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/733/1323/","by":{"1":"14, 15","2":"24"}},{"t":"case","label":"Hurley v. Irish-American Gay, Lesbian & Bisexual Grp. of Bos., Inc.","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"1":"26, 27"}},{"t":"case","label":"Knoxville Traction Co. v. Lane","cite":"53 S.W. 557","y":1899,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./53/557/","by":{"1":"27"}},{"t":"case","label":"Kyles v. J.K. Guardian Sec. Servs., Inc.","cite":"222 F.3d 289","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/222/289/","by":{"1":"14"}},{"t":"case","label":"Langer v. Music City Hotel LP","cite":"2021 WL 5919825","y":2021,"court":"N.D. Cal. Dec. 15","by":{"1":"31"}},{"t":"case","label":"Laufer v. Arpan LLC","cite":"65 F.4th 615","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/615/","by":{"1":"20","2":"30"}},{"t":"case","label":"Mosley v. Kohl’s Dep’t Stores, Inc.","cite":"942 F.3d 752","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/752/","by":{"1":"14, 16","2":"24"}},{"t":"case","label":"Molski v. Evergreen Dynasty Corp.","cite":"500 F.3d 1047","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/500/1047/","by":{"1":"16, 17","2":"46"}},{"t":"case","label":"Nanni v. Aberdeen Marketplace, Inc.","cite":"878 F.3d 447","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/878/447/","by":{"1":"14","2":"24"}},{"t":"case","label":"Newman v. Piggie Park Enters., Inc.","cite":"390 U.S. 400","y":1968,"id":"1967/339","sc":1,"sum":"One who succeeds in obtaining an injunction under Title II of the Civil Rights Act of 1964 should ordinarily recover an attorney's fee under § 204 (b) unless special circumstances would render such an award unjust, and should not be limited, as the Court of Appeals held, to an award of counsel fees only if the defenses advanced were \"for purposes of delay and not in good faith.\" 377 F. 2d 433, modified and affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","2":"47"}},{"t":"case","label":"PGA Tour, Inc. v. Martin","cite":"532 U.S. 661","y":2001,"id":"2000/00-24","sc":1,"sum":"The Court held that Title III of the ADA, by its plain terms, prohibits the PGA from denying Martin equal access to its tours on the basis of his disability and that allowing Martin to use a cart, despite the walking rule, is not a modification that would \"fundamentally alter the nature\" of the game. \"The purpose of the walking rule is... not compromised in the slightest by allowing Martin to use a cart,\" wrote Justice Stevens, noting Martin's fatiguing disability.","sumSrc":"Oyez","by":{"1":"2, 3","2":"4, 38"}},{"t":"case","label":"Pickern v. Holiday Quality Foods Inc.","cite":"293 F.3d 1133","y":2002,"url":"https://www.courtlistener.com/c/F.3d/293/1133/","by":{"1":"15"}},{"t":"case","label":"Scherr v. Marriott Int’l, Inc.","cite":"703 F.3d 1069","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/703/1069/","by":{"1":"15"}},{"t":"case","label":"Sinochem Int’l Co. v. Malaysia Int’l Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"op":2,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Smith v. Pacific Props. & Dev. Corp.","cite":"358 F.3d 1097","y":2004,"url":"https://www.courtlistener.com/c/F.3d/358/1097/","by":{"1":"14"}},{"t":"case","label":"Strojnik v. International Hospitality Enters., Inc.","cite":"2021 WL 5630352","y":2021,"court":"D.P.R. Jan. 4","by":{"1":"31"}},{"t":"case","label":"Tandy v. City of Wichita","cite":"380 F.3d 1277","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/380/1277/","by":{"1":"14"}},{"t":"case","label":"US Airways, Inc. v. Barnett","cite":"535 U.S. 391","y":2002,"id":"2001/00-1250","sc":1,"sum":"The Court held that the ADA did not require the employer to assign the employee to the mailroom position in violation of the established seniority system. The Court reasoned that an employer's showing that a requested accommodation conflicts with seniority rules is ordinarily sufficient to show that an accommodation is not reasonable.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Village of Bellwood v. Dwivedi","cite":"895 F.2d 1521","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/1521/","by":{"1":"14"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 25"}},{"t":"case","label":"Whitaker v. Montes","cite":"2021 WL 5113218","y":2021,"court":"N.D. Cal. Nov. 3","by":{"1":"31"}},{"t":"case","label":"Winzler v. Toyota Motor Sales, U.S.A., Inc.","cite":"681 F.3d 1208","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/681/1208/","by":{"1":"32"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"1, 6, 9-13, 17, 20-22, 24, 25, 29, 32"}},{"t":"usc","label":"42 U.S.C. § 12111","url":"https://www.law.cornell.edu/uscode/text/42/12111","by":{"1":"23"}},{"t":"usc","label":"42 U.S.C. § 12131","url":"https://www.law.cornell.edu/uscode/text/42/12131","by":{"1":"14"}},{"t":"usc","label":"42 U.S.C. § 12132","url":"https://www.law.cornell.edu/uscode/text/42/12132","by":{"1":"14"}},{"t":"usc","label":"42 U.S.C. § 12201","url":"https://www.law.cornell.edu/uscode/text/42/12201","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 2000a","url":"https://www.law.cornell.edu/uscode/text/42/2000a","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","by":{"1":"14"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"1":"25"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"1":"14"}},{"t":"usc","label":"42 U.S.C. § 3616a","url":"https://www.law.cornell.edu/uscode/text/42/3616a","subs":["(b)(2)(A)","(b)(2)(E)"],"by":{"1":"16, 16"}},{"t":"usc","label":"2 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/2/431","by":{"1":"28"}},{"t":"usc","label":"29 U.S.C. § 794","url":"https://www.law.cornell.edu/uscode/text/29/794","by":{"1":"14"}},{"t":"reg","label":"28 C.F.R. pt. 36","url":"https://www.ecfr.gov/current/title-28/part-36","by":{"1":"4, 5, 19, 22, 31","2":"6, 27, 50"}},{"t":"case","label":"303 Creative LLC v. Elenis","cite":"143 S. Ct. 2298","y":2023,"id":"2022/21-476","sc":1,"sum":"The First Amendment prohibits Colorado from forcing a website designer to create expressive designs speaking messages with which the designer disagrees.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18, 36, 38, 41"}},{"t":"case","label":"Adarand Constructors, Inc. v. Pena","cite":"515 U.S. 200","y":1995,"id":"1994/93-1841","sc":1,"sum":"The Court found that in order to uphold the Fifth Amendment, strict scrutiny must be applied if race is the sole indicator of disadvantage.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Alexander v. Choate","cite":"469 U.S. 287","y":1985,"id":"1984/83-727","sc":1,"sum":"Assuming that § 504 or its implementing regulations reach some claims of disparate-impact discrimination, the effect of Tennessee's reduction in annual inpatient hospital coverage is not among them.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Bank of Am. Corp. v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"C.R. Educ. & Enf’t Ctr. v. Hosp. Props. Tr.","cite":"867 F.3d 1093","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1093/","by":{"2":"24"}},{"t":"case","label":"Carello v. Aurora Policemen Credit Union","cite":"930 F.3d 830","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/830/","ar":1,"sum":"Observing with respect to a Title III disability discrimination claim, “[t]here is no doubt that dignitary harm is cognizable; stigmatic injury is ‘one of the most serious consequences’ of discrimination”.","sumSrc":"brief:2","by":{"2":"36","3":"6, 7"}},{"t":"case","label":"City of Mesquite v. Aladdin’s Castle, Inc.","cite":"455 U.S. 283","y":1982,"id":"1981/80-1577","sc":1,"sum":"Section 6 of appellant Texas city's licensing ordinance governing coin-operated amusement establishments directs the Chief of Police to consider whether a license applicant has any \"connections with criminal elements.\" After receiving recommendations from the Chief of Police, the Chief Building Inspector, and the City Planner, the City Manager decides whether to grant a license. If he denies the license, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"D’Lil v. Best W. Encina Lodge & Suites","cite":"538 F.3d 1031","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/538/1031/","by":{"2":"44"}},{"t":"case","label":"De Wolf v. Ford","cite":"193 N.Y. 397","y":1908,"url":"https://www.courtlistener.com/c/N.Y./193/397/","by":{"2":"42"}},{"t":"case","label":"Emmke v. De Silva","cite":"293 F. 17","y":1923,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./293/17/","by":{"2":"43"}},{"t":"case","label":"Ferguson v. Gies","cite":"82 Mich. 358","y":1890,"url":"https://www.courtlistener.com/c/Mich./82/358/","op":1,"by":{"2":"43"}},{"t":"case","label":"Frewen v. Page","cite":"238 Mass. 499","y":1921,"url":"https://www.courtlistener.com/c/Mass./238/499/","by":{"2":"42"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Env’t Servs. (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Gratz v. Bollinger","cite":"539 U.S. 244","y":2003,"id":"2002/02-516","sc":1,"sum":"The Court held that the University of Michigan's practice of favoring applicants of certain races in the admissions process violated the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Grutter v. Bollinger","cite":"539 U.S. 306","y":2003,"id":"2002/02-241","sc":1,"sum":"The Court held that the use of race in the University of Michigan's Law School admissions decisions did not violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Haaland v. Brackeen","cite":"143 S. Ct. 1609","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"35"}},{"t":"case","label":"Harty v. W. Point Realty, Inc.","cite":"28 F.4th 435","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/28/435/","op":1,"by":{"2":"11"}},{"t":"case","label":"Heart of Atlanta Motel, Inc. v. United States","cite":"379 U.S. 241","y":1964,"id":"1964/515","sc":1,"sum":"The Court found that hotels did not have the right to discriminate against black guests under Title II of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Jackson v. Virginia Hot Springs Co.","cite":"213 F. 969","y":1914,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F./213/969/","by":{"2":"42","3":"10"}},{"t":"case","label":"Laufer v. Alamac Inc.","cite":"2021 WL 4765435","y":2021,"court":"D.C. Cir. Sept. 10","by":{"2":"11"}},{"t":"case","label":"Laufer v. Looper","cite":"22 F.4th 871","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/22/871/","by":{"2":"11"}},{"t":"case","label":"Laufer v. Mann Hosp., LLC","cite":"996 F.3d 269","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/996/269/","by":{"2":"11"}},{"t":"case","label":"Laufer v. Naranda Hotels, LLC","cite":"60 F.4th 156","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/156/","by":{"2":"11"}},{"t":"case","label":"Markham v. Brown","cite":"8 N.H. 523","y":1837,"url":"https://www.courtlistener.com/c/N.H./8/523/","by":{"2":"42"}},{"t":"case","label":"Mission Prod. Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"sum":"A bankruptcy debtor’s rejection of an executory contract under 11 U. S. C. §365 has the same effect as a breach of that contract outside bankruptcy; such an act thus cannot rescind rights that the contract previously granted.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"49"}},{"t":"case","label":"Missouri ex rel. Gaines v. Canada","cite":"305 U.S. 337","y":1938,"id":"1900-1940/305us337","sc":1,"sum":"The Court held that Missouri's lack of a black students' law school, which forced students to attend similar schools out of state, violated the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Ne. Fla. Chapter of the Associated Gen. Contractors of Am. v. City of Jacksonville","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"sum":"The majority determined that the association members' possible lack of fair opportunity as a consequence of the ordinance would have constituted injury. Since the association members would have competed for the reserved city contracts in the absence of the ordinance, the Court found that they did have standing and reversed the judgment of the Court of Appeals.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Nw. Airlines, Inc. v. Cnty. of Kent","cite":"510 U.S. 355","y":1994,"id":"1993/92-97","sc":1,"sum":"Respondents, the owner and operators of Michigan's Kent County International Airport (collectively, the Airport), collect rent and fees from three groups of Airport users: commercial airlines, including petitioners (Airlines); general aviation; and concessionaires such as car rental agencies and gift shops. The Airport allocates its air-operations costs---e. g., maintaining runways-to the Airlines and general …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31"}},{"t":"case","label":"Regents of the Univ. of Cal. v. Bakke","cite":"438 U.S. 265","y":1978,"id":"1979/76-811","sc":1,"sum":"The Court found that any racial quota for the purpose of admissions supported by a government entity violates the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Suarez-Torres v. Panaderia y Reposteria Espana, Inc.","cite":"988 F.3d 542","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/988/542/","by":{"2":"24"}},{"t":"case","label":"Tennessee v. Lane","cite":"541 U.S. 509","y":2004,"id":"2003/02-1667","sc":1,"sum":"In a 5-to-4 opinion written by Justice John Paul Stevens, the Court held that Congress had sufficiently demonstrated the problems faced by disabled persons who sought to exercise fundamental rights protected by the Due Process clause of the 14th Amendment (such as access to a court).","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Thomas v. Pick Hotels Corp.","cite":"224 F.2d 664","y":1955,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/224/664/","sum":"Noting that state laws prohibiting discrimination in public accommodations are “merely declaratory of the common law”.","sumSrc":"brief:2","by":{"2":"43"}},{"t":"usc","label":"42 U.S.C. § 12102","url":"https://www.law.cornell.edu/uscode/text/42/12102","by":{"2":"7"}},{"t":"case","label":"Griffin v. Department of Labor Federal Credit Union","cite":"912 F.3d 649","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/649/","by":{"3":"6, 7"}},{"t":"case","label":"Laufer v. Arpan LLC","cite":"2023 WL 5209551","y":2023,"court":"11th Cir. Aug. 15","by":{"3":"23"}},{"t":"case","label":"Natural Resources Defense Council, Inc. v. Texaco Refining & Marketing, Inc.","cite":"2 F.3d 493","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/2/493/","op":1,"by":{"3":"24"}},{"t":"reg","label":"Nondiscrimination on the Basis of Disability by Public Accommodations and in Commercial Facilities, 75 Fed. Reg. 56,236","url":"https://www.govinfo.gov/link/fr/75/56236","by":{"3":"4"}}]};